 await expect(page.getByRole('dialog')).toHaveCount(0);
 await expect(page.locator('.book-card')).toHaveCount(7);
 const card = page.locator('.book-card').filter({has:page.locator('.book-title',{hasText:'Piranesi'})});
 await card.getByRole('button',{name:'Mark as finished'}).click();
 await expect(card.locator('.status-label')).toHaveText('Finished');
 await card.getByRole('link',{name:'Piranesi',exact:true}).click();
 await expect(page.getByRole('heading',{name:'Piranesi',exact:true})).toBeVisible();
 await expect(page.locator('.detail-author')).toHaveText('by Susanna Clarke');
 await expect(page.locator('.notes-body')).toHaveText('A house full of wonders.');
 await page.getByRole('button',{name:'Edit notes'}).click();
 await page.getByRole('textbox',{name:'My notes'}).fill('The beauty of the House is immeasurable.\\nA favorite to read again.');
 await page.getByRole('button',{name:'Save notes'}).click();
 await expect(page.locator('.notes-body')).toContainText('A favorite to read again.');
 await page.getByRole('button',{name:'Share book'}).click();
 await expect(page.getByRole('status')).toContainText('Book link copied');
 const copied = await page.evaluate(()=>navigator.clipboard.readText());
 expect(copied).toBe(page.url());
 const sharedPage=await context.newPage();
 await sharedPage.goto(copied);
 await expect(sharedPage.getByRole('heading',{name:'Piranesi',exact:true})).toBeVisible();
 await expect(sharedPage.locator('.notes-body')).toContainText('A favorite to read again.');
 await sharedPage.reload();
 await expect(sharedPage.locator('.detail-status')).toHaveText('Finished');
 await sharedPage.close();
 await page.getByRole('button',{name:'Read again'}).click();
 await expect(page.locator('.detail-status')).toHaveText('Currently reading');
 await page.screenshot({path:'/tmp/folio-detail.png',fullPage:true});
 await page.goto('http://localhost:3001/books/missing-book');
 await expect(page.getByRole('heading',{name:'This chapter is missing.'})).toBeVisible();
 await page.goto('http://localhost:3000');
 await expect(page.locator('.book-card')).toHaveCount(6);
 await page.evaluate(()=>document.fonts.ready);
 await page.screenshot({path:'/tmp/folio-desktop-final.png',fullPage:true});
 for(const width of [390,320,768]){
  await page.setViewportSize({width,height:844});
  expect(await page.evaluate(()=>document.documentElement.scrollWidth<=window.innerWidth),"'`No overflow at ${width}px`).toBe(true);
 }
 await page.setViewportSize({width:390,height:844});
 await page.screenshot({path:'"'/tmp/folio-mobile-final.png',fullPage:true});
 await page.getByRole('button',{name:'Add a book',exact:true}).click();
 await expect(page.getByRole('dialog')).toBeVisible();
 expect(await page.getByLabel('Book title').evaluate(el=>document.activeElement===el)).toBe(true);
 await page.screenshot({path:'/tmp/folio-modal.png',fullPage:true});
 await page.keyboard.press('Escape');
 await expect(page.getByRole('dialog')).toHaveCount(0);
 expect(errors).toEqual([]);
 console.log('PASS: add book, finish, edit notes, clipboard sharing, direct link, reload, read again, search, filters, sorting, missing book, mobile layouts, keyboard dialog, and no browser errors.');
